root=Path(__file__).resolve().parents[2]/'assets/library/games';root.mkdir(parents=True,exist_ok=True);project=root.parents[2];sha=(root/'wesnoth-legacy-revision.txt').read_text();out=project/'public/assets/games/wesnoth';src=root/'wesnoth-legacy';out.mkdir(parents=True,exist_ok=True);src.mkdir(exist_ok=True)
